INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'access', 'n./vt.', '/ˈækses/', '通道;(使用、查阅的)机会;进入;获取', 'Everyone should have access to the Internet and new technology.', '每个人都应该能接触到互联网和新技术。', 'The Internet', 1, 0, 'senior', 'wordlist', 'required2', 'U3', 'have access to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'account', 'n.', '/əˈkaʊnt/', '账户;描述;说明', 'Never share the password of your online account with strangers.', '绝不要把你网上账户的密码告诉陌生人。', 'The Internet', 2, 0, 'senior', 'wordlist', 'required2', 'U3', 'an online account', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'author', 'n.', '/ˈɔːθə(r)/', '作者;作家', 'The author of the blog gives tips on how to stay safe online.', '这篇博客的作者给出了如何安全上网的建议。', 'The Internet', 3, 0, 'senior', 'wordlist', 'required2', 'U3', 'the author of the blog', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'battery', 'n.', '/ˈbætri/', '电池', 'I downloaded the software to help my phone battery last longer.', '我下载了这个软件来让我的手机电池更耐用。', 'The Internet', 4, 0, 'senior', 'wordlist', 'required2', 'U3', 'phone battery', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'benefit', 'n./vt./vi.', '/ˈbenɪfɪt/', '益处;使受益;得益于', 'One of the greatest benefits of the Internet is connecting people.', '互联网最大的好处之一是把人们联系起来。', 'The Internet', 5, 0, 'senior', 'wordlist', 'required2', 'U3', 'a great benefit', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'blog', 'n./vi.', '/blɒɡ/', '博客;写博客', 'Today I want to blog about how to stay safe online.', '今天我想写篇博客谈谈如何安全上网。', 'The Internet', 6, 0, 'senior', 'wordlist', 'required2', 'U3', 'write a blog', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'blogger', 'n.', '/ˈblɒɡə(r)/', '博客作者;博主', 'Many years as a blogger have taught me a thing or two about the Internet.', '多年的博主经历让我对互联网懂得了一些门道。', 'The Internet', 7, 0, 'senior', 'wordlist', 'required2', 'U3', 'an experienced blogger', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'button', 'n.', '/ˈbʌtn/', '按钮;纽扣', 'Have you pressed the button yet to copy the file?', '你按按钮复制文件了吗?', 'The Internet', 8, 0, 'senior', 'wordlist', 'required2', 'U3', 'press the button', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'cash', 'n.', '/kæʃ/', '现金;金钱', 'We no longer have to carry cash around when we go shopping online.', '我们网购时不再需要随身带现金了。', 'The Internet', 9, 0, 'senior', 'wordlist', 'required2', 'U3', 'carry cash', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'charity', 'n.', '/ˈtʃærəti/', '慈善;慈善机构(或组织)', 'Her next goal is to start a charity website to raise money for children.', '她下一个目标是创建一个慈善网站为孩子们筹钱。', 'The Internet', 10, 0, 'senior', 'wordlist', 'required2', 'U3', 'a charity website', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'chat', 'vi.', '/tʃæt/', '聊天;闲聊', 'I especially like to chat with my friends and family online.', '我特别喜欢在网上和朋友家人聊天。', 'The Internet', 11, 0, 'senior', 'wordlist', 'required2', 'U3', 'chat online', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'click', 'vt./vi.', '/klɪk/', '点击', 'Don''t click on anything that makes you feel uncomfortable.', '不要点击任何让你感到不舒服的东西。', 'The Internet', 12, 0, 'senior', 'wordlist', 'required2', 'U3', 'click on the link', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'conference', 'n.', '/ˈkɒnfərəns/', '会议;研讨会;正式会谈', 'For the past few years, Wuzhen has hosted the World Internet Conference.', '过去几年里,乌镇主办了世界互联网大会。', 'The Internet', 13, 0, 'senior', 'wordlist', 'required2', 'U3', 'the World Internet Conference', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'confirm', 'vt.', '/kənˈfɜːm/', '确认;使确信', 'Have you confirmed the Wi-Fi password?', '你确认过 Wi-Fi 密码了吗?', 'The Internet', 14, 0, 'senior', 'wordlist', 'required2', 'U3', 'confirm the password', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'convenient', 'adj.', '/kənˈviːniənt/', '方便的;近便的', 'The Internet has made our lives more convenient.', '互联网让我们的生活更方便了。', 'The Internet', 15, 0, 'senior', 'wordlist', 'required2', 'U3', 'more convenient', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'cyberbully', 'n./vt.', '/ˈsaɪbəbʊli/', '网霸;网络欺凌', 'Be polite so that you don''t become a target for a troll or cyberbully.', '要有礼貌,这样你才不会成为喷子或网霸的目标。', 'The Internet', 16, 0, 'senior', 'wordlist', 'required2', 'U3', 'become a target for a cyberbully', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'database', 'n.', '/ˈdeɪtəbeɪs/', '数据库;资料库', 'We can get the most updated information from large databases.', '我们能从大型数据库中获取最新的信息。', 'The Internet', 17, 0, 'senior', 'wordlist', 'required2', 'U3', 'a large database', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'define', 'vt.', '/dɪˈfaɪn/', '给……下定义;界定;解释', 'A good blog post should define new words for its readers.', '一篇好的博文应该为读者解释新词。', 'The Internet', 18, 0, 'senior', 'wordlist', 'required2', 'U3', 'define a new word', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'discount', 'n./vt.', '/ˈdɪskaʊnt/', '折扣;打折', 'Laura needs an app that will help her get discounts when shopping.', '劳拉需要一个能在购物时帮她拿折扣的应用。', 'The Internet', 19, 0, 'senior', 'wordlist', 'required2', 'U3', 'get a discount', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'distance', 'n.', '/ˈdɪstəns/', '距离', 'The Internet can remove the distance that exists between people.', '互联网能消除人与人之间的距离。', 'The Internet', 20, 0, 'senior', 'wordlist', 'required2', 'U3', 'remove the distance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'embarrassing', 'adj.', '/ɪmˈbærəsɪŋ/', '让人难堪(尴尬;害羞)的', 'A cyberbully may post embarrassing photos about other people.', '网霸可能会发布有关他人的难堪照片。', 'The Internet', 21, 0, 'senior', 'wordlist', 'required2', 'U3', 'embarrassing photos', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'engine', 'n.', '/ˈendʒɪn/', '引擎;发动机', 'A search engine is a tool that helps you find what you''re looking for.', '搜索引擎是一种帮你找到所需内容的工具。', 'The Internet', 22, 0, 'senior', 'wordlist', 'required2', 'U3', 'a search engine', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'false', 'adj.', '/fɔːls/', '假的;错误的', 'Trolls often use several false names so that they can stay on a site.', '喷子常用好几个假名以便留在网站上。', 'The Internet', 23, 0, 'senior', 'wordlist', 'required2', 'U3', 'false names', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'familiar', 'adj.', '/fəˈmɪliə(r)/', '熟悉的;熟知的', 'Use a website that you are familiar with when shopping online.', '网购时使用你熟悉的网站。', 'The Internet', 24, 0, 'senior', 'wordlist', 'required2', 'U3', 'be familiar with', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'file', 'n.', '/faɪl/', '文件;文件夹;档案', 'Click the button to copy the file to your computer.', '点击按钮把文件复制到你的电脑上。', 'The Internet', 25, 0, 'senior', 'wordlist', 'required2', 'U3', 'copy the file', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'function', 'n./vi.', '/ˈfʌŋkʃn/', '功能;作用;起作用', 'A kind of new PC has been built with more functions.', '一种功能更多的新电脑已被造出来了。', 'The Internet', 26, 0, 'senior', 'wordlist', 'required2', 'U3', 'more functions', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'guideline', 'n.', '/ˈɡaɪdlaɪn/', '准则;指导原则', 'The author provides clear guidelines for staying safe online.', '作者提供了安全上网的明确准则。', 'The Internet', 27, 0, 'senior', 'wordlist', 'required2', 'U3', 'safety guidelines', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'identity', 'n.', '/aɪˈdentəti/', '身份;个性', 'Someone might use the information to steal your identity online.', '有人可能会用这些信息在网上盗用你的身份。', 'The Internet', 28, 0, 'senior', 'wordlist', 'required2', 'U3', 'steal your identity', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'inspire', 'vt.', '/ɪnˈspaɪə(r)/', '鼓舞;激励;启发', 'She was so inspired by the people she met online that she started a club.', '她受网上结识的人鼓舞,以至于创办了一个俱乐部。', 'The Internet', 29, 0, 'senior', 'wordlist', 'required2', 'U3', 'be inspired by', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'network', 'n.', '/ˈnetwɜːk/', '(互联)网络;网状系统;人际网', 'People''s lives have been changed by online communities and social networks.', '人们的生活被网络社区和社交网络改变了。', 'The Internet', 30, 0, 'senior', 'wordlist', 'required2', 'U3', 'a social network', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'particular', 'adj.', '/pəˈtɪkjələ(r)/', '特定的;特别的;讲究的', 'A cyberbully often writes mean things directed at particular people.', '网霸常写针对特定人的刻薄话。', 'The Internet', 31, 0, 'senior', 'wordlist', 'required2', 'U3', 'particular people', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'press', 'vt.', '/pres/', '按,压;敦促', 'You get a message whenever someone presses the update button.', '每当有人按下更新按钮,你就会收到一条消息。', 'The Internet', 32, 0, 'senior', 'wordlist', 'required2', 'U3', 'press the button', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'privacy', 'n.', '/ˈprɪvəsi/', '隐私;私密', 'Protect your privacy and don''t give out your address or phone number.', '保护好你的隐私,不要透露你的地址或电话号码。', 'The Internet', 33, 0, 'senior', 'wordlist', 'required2', 'U3', 'protect your privacy', '美音 /ˈpraɪvəsi/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'province', 'n.', '/ˈprɒvɪns/', '省', 'Wuzhen is a small waterside town in Zhejiang Province.', '乌镇是浙江省一个小小的水乡。', 'The Internet', 34, 0, 'senior', 'wordlist', 'required2', 'U3', 'Zhejiang Province', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'resident', 'n.', '/ˈrezɪdənt/', '居民;住户', 'Residents here can go online as easily as in large modern cities.', '这里的居民能像大城市里一样轻松地上网。', 'The Internet', 35, 0, 'senior', 'wordlist', 'required2', 'U3', 'local residents', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'rude', 'adj.', '/ruːd/', '粗鲁的;无礼的', 'Being online is no excuse for being rude to others.', '上网不是对别人无礼的借口。', 'The Internet', 36, 0, 'senior', 'wordlist', 'required2', 'U3', 'be rude online', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'software', 'n.', '/ˈsɒftweə(r)/', '软件', 'We can download software, documents, and images whenever we need them.', '我们需要时随时都能下载软件、文档和图片。', 'The Internet', 37, 0, 'senior', 'wordlist', 'required2', 'U3', 'download software', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'stream', 'vt./vi./n.', '/striːm/', '流播(在线播放音视频);流出;小河', 'Plus they can stream movies and music at high speeds.', '而且他们能高速流播电影和音乐。', 'The Internet', 38, 0, 'senior', 'wordlist', 'required2', 'U3', 'stream movies', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'surf', 'vt./vi.', '/sɜːf/', '浏览;冲浪', 'She discovered that surfing the Internet could help her feel less lonely.', '她发现上网浏览能帮她减少孤独感。', 'The Internet', 39, 0, 'senior', 'wordlist', 'required2', 'U3', 'surf the Internet', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'target', 'n./vt.', '/ˈtɑːɡɪt/', '目标;对象;把……作为攻击目标', 'You don''t want to become a target for a troll or cyberbully.', '你不会想成为喷子或网霸的攻击目标。', 'The Internet', 40, 0, 'senior', 'wordlist', 'required2', 'U3', 'a target for a troll', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'theft', 'n.', '/θeft/', '偷(窃);盗窃罪', 'Identity theft is a common and serious problem on the Internet.', '身份盗窃是互联网上一个常见而严重的问题。', 'The Internet', 41, 0, 'senior', 'wordlist', 'required2', 'U3', 'identity theft', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tip', 'n.', '/tɪp/', '忠告;诀窍;实用的提示', 'Do you have any tips for how to surf the Internet safely?', '你有没有安全上网的小窍门?', 'The Internet', 42, 0, 'senior', 'wordlist', 'required2', 'U3', 'useful tips', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tough', 'adj.', '/tʌf/', '艰难的;严厉的', 'When you go through tough times, you meet others facing similar challenges.', '当你度过艰难时期时,会遇到面临类似挑战的人。', 'The Internet', 43, 0, 'senior', 'wordlist', 'required2', 'U3', 'tough times', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'troll', 'n.', '/trɒl/', '发挑衅帖子的人;恶意挑衅的帖子', 'A troll is a person who posts comments in order to stir up trouble online.', '喷子是那种为了在网上惹是生非而发帖的人。', 'The Internet', 44, 0, 'senior', 'wordlist', 'required2', 'U3', 'a troll online', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'update', 'vt./n.', '/ˌʌpˈdeɪt/', '更新;最新消息', 'You get a message whenever there has been an update.', '每当有更新时,你就会收到一条消息。', 'The Internet', 45, 0, 'senior', 'wordlist', 'required2', 'U3', 'the most updated information', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'upset', 'adj.', '/ʌpˈset/', '心烦的;苦恼的;沮丧的', 'The girl was very upset after she was made fun of online.', '那个女孩在网上被取笑后非常难过。', 'The Internet', 46, 0, 'senior', 'wordlist', 'required2', 'U3', 'feel upset', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'Wi-Fi', 'n.', '/ˈwaɪfaɪ/', '无线保真;无线网络', 'Have you confirmed the Wi-Fi password for the new network?', '你确认过新网络的 Wi-Fi 密码了吗?', 'The Internet', 47, 0, 'senior', 'wordlist', 'required2', 'U3', 'the Wi-Fi password', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'comment', 'n./vi.', '/ˈkɒment/', '评论;议论', 'Has anyone made a comment about the online database yet?', '有人对这个在线数据库发表评论了吗?', 'The Internet', 48, 0, 'senior', 'wordlist', 'required2', 'U3', 'post a comment', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r2u3.01', '①肯定句 has/have been + 过去分词', 'A2', 10, '必修二 U3 — 主语是动作承受者时,现在完成时被动用 has/have been + 过去分词;单数主语用 has been done,复数/I/you/we/they 用 have been done。', 1, 'required2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r2u3.02', '②否定与疑问(hasn''t/haven''t been done;Has/Have ... been done?)', 'A2', 10, '必修二 U3 — 否定在 has/have 后加 not(hasn''t/haven''t been done);一般疑问把 has/have 提到主语前:Has/Have + 主语 + been + 过去分词?', 2, 'required2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r2u3.03', '③与时间状语连用 / 主动↔被动转换 / by 短语', 'A2', 10, '必修二 U3 — 常与 already/yet/just/recently 等连用,时间词位置与现在完成时一致;主动句变被动句时,宾语作主语、动作执行者用 by 引出。', 3, 'required2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.01'), 'The new software ____ to my phone, so it runs much faster now.', 'has been downloaded', 'has downloaded', 'is downloading', 'downloaded', 'A', '主语 software 是被下载的对象 → 现在完成时被动 has been downloaded。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.01'), 'A kind of new PC ____ with many more useful functions.', 'has built', 'has been built', 'is building', 'built', 'B', 'PC 是被建造的对象 → has been built。', 2, 2, 'mcq');
