INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.02'), '____ the Wi-Fi password been confirmed yet?', 'Has', 'Have', 'Is', 'Did', 'A', '单数主语 password,疑问句把 has 提前 → Has ... been confirmed?', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.02'), 'The software ____ been downloaded, so my phone is still slow.', 'isn''t', 'hasn''t', 'doesn''t', 'didn''t', 'B', '现在完成时被动否定 → hasn''t been downloaded。', 2, 2, 'mcq');
