INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.02'), 'The Wi-Fi ____ been set up in the old town, so people there can''t go online.', 'isn''t', 'doesn''t', 'wasn''t', 'hasn''t', 'D', '单数 Wi-Fi,否定 → hasn''t been set up。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'The software has ____ been downloaded, so you can use it right away.', 'just', 'ever', 'never', 'soon', 'A', '现在完成时被动 + just,表''刚刚被下载'',符合下文''马上能用''。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'The Wi-Fi password has ____ been confirmed, so we no longer have to wait.', 'yet', 'already', 'tomorrow', 'long ago', 'B', '肯定句中表''已经''用 already;yet 用于否定/疑问,且时间副词须与现在完成时搭配。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'The file hasn''t been copied ____, so please press the button again.', 'already', 'just now', 'yet', 'ago', 'C', '否定句句末''还没''用 yet。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'Jan''s life has been greatly improved ____ the Internet.', 'of', 'with', 'from', 'by', 'D', '被动句中动作执行者用 by 引出 → by the Internet。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), '"The company has updated the app." In the passive voice: "The app ____ by the company."', 'has been updated', 'has updated', 'updated', 'is updating', 'A', '主动变被动:宾语 the app 作主语 → has been updated by the company。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'Much has ____ been written about the dangers of sharing too much online.', 'yesterday', 'recently', 'long', 'once upon', 'B', 'recently 可与现在完成时连用,表''近来已被写了很多''。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), '"Someone has lost an identity card." In the passive voice: "An identity card ____."', 'has lost', 'lost', 'has been lost', 'is losing', 'C', '主动变被动:宾语 an identity card 作主语 → has been lost。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'The new functions have ____ been added, so there is nothing left to install.', 'yet', 'ago', 'never', 'all', 'D', 'all 在肯定句中强调''全部已被加上'';yet/never 不符合下文''没有剩下的''。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'Have the photos been deleted ____? I really hope they are gone now.', 'yet', 'already done', 'ago', 'long since', 'A', '疑问句句末''到现在''用 yet。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), '"People have helped many older learners." In the passive voice: "Many older learners ____."', 'have helped', 'have been helped', 'helped', 'are helping', 'B', '主动变被动:宾语 learners 作主语(复数)→ have been helped。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'The website has ____ been visited by thousands of people since it opened.', 'yet', 'tomorrow', 'already', 'next week', 'C', '肯定句表''已经''用 already,且与 since 引导的现在完成时一致。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'These embarrassing photos have ____ been removed, so she still feels upset.', 'ever', 'just', 'already', 'not', 'D', 'have not been removed 表''还没被删除'',与下文''仍然难过''一致。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), '"They have built a faster network." In the passive voice: "A faster network ____."', 'has been built', 'has built', 'built', 'is building', 'A', '主动变被动:宾语 network 作主语 → has been built。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'The town''s transport has ____ been changed by the Internet in recent years.', 'long ago', 'greatly', 'yesterday', 'tomorrow', 'B', 'greatly 作程度状语,与现在完成时被动连用,表''被极大改变''。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'Has the database been searched ____? We need the result before noon.', 'ago', 'long since', 'yet', 'tomorrow', 'C', '疑问句句末用 yet。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), '"The blogger has answered the question many times." Passive: "The question ____ many times."', 'has answered', 'answered', 'is answering', 'has been answered', 'D', '主动变被动:宾语 question 作主语 → has been answered。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'The app has ____ been updated, so all the bugs are now fixed.', 'recently', 'ago', 'yesterday', 'long', 'A', 'recently 与现在完成时连用,表''近来已被更新''。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'Public bikes have been rented in the town ____ online apps, not paperwork.', 'by use', 'by using', 'with using', 'of using', 'B', '''通过……方式''用 by + doing → by using online apps。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), '"Cyberbullies have attacked many users." Passive: "Many users ____ by cyberbullies."', 'have attacked', 'attacked', 'have been attacked', 'are attacking', 'C', '主动变被动:宾语 users 作主语(复数)→ have been attacked。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U3' AND code='r2u3.03'), 'The comment has ____ been posted, so everyone can read it now.', 'yet', 'tomorrow', 'long since', 'already', 'D', '肯定句表''已经''用 already,与下文''现在大家都能读到''一致。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'How the Internet Changed Our Lives', 'Much has been written about the wonders of the World Wide Web, and most of it tells us how the Internet has made our daily lives far more convenient. When we go shopping, we no longer have to wait in a long line or carry cash around. With just a few clicks, we can buy what we want and have it sent right to our door. We can also get the most updated information from large databases, and we can download software, documents, and images whenever we need them. But the Internet has done much more than simply make life easier. It has also changed the way people connect with one another. Through online communities and social networks, people who live far apart can share their feelings, support each other, and feel less lonely. In this way, the Internet has removed much of the distance that once stood between people, bringing the world closer together than ever before.', '说明·互联网让生活更方便', 158, '[{"q":"What does the writer say we no longer need to do when shopping online?","answer":"A","options":["Stand in a queue or take banknotes with us.","Use any computer at all.","Talk to other shoppers.","Visit large databases."],"explanation":"原文 ''no longer have to wait in a long line or carry cash around'' 的转述。"},{"q":"Besides making life easier, what else has the Internet changed?","answer":"B","options":["The price of all goods.","How people stay in touch with each other.","The speed of every computer.","The weather around the world."],"explanation":"原文 ''changed the way people connect with one another''(中段)。"},{"q":"What is the main effect of online communities, according to the text?","answer":"A","options":["They help people feel less lonely and closer together.","They make software cheaper.","They make people travel more.","They replace all real friends."],"explanation":"末段 ''feel less lonely… bringing the world closer together'' 的转述。"}]'::jsonb, '[{"word":"convenient","cn":"方便的"},{"word":"database","cn":"数据库"},{"word":"download","cn":"下载"},{"word":"distance","cn":"距离"}]'::jsonb, 2, 'required2', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Jan''s New Life Online', 'Jan was an English teacher in Birmingham who suddenly fell seriously ill and had to give up her job. At fifty, she found herself out of work and stuck at home with only her computer for company. After a while, she found that surfing the Internet helped her feel less lonely and bored. She could listen to music, watch films, and explore the world without leaving her room. She also joined an online group where she could talk about her problems and get advice from others. She was so inspired by the people she met online that she decided to start an IT club to teach older people how to use computers. Many people have been helped by her club. One man learnt to look for work online and found a good job, while a woman who lived alone started a small online company with two friends. Jan now believes that everyone should be able to enjoy the benefits of the Internet, whatever their age.', '记叙·Jan 与网络社区', 165, '[{"q":"Why did Jan have to stop working?","answer":"B","options":["She wanted a long holiday.","She became seriously ill.","She moved to another city.","She disliked teaching."],"explanation":"原文 ''fell seriously ill and had to give up her job'' 的转述。"},{"q":"What made Jan decide to start the IT club?","answer":"C","options":["Her doctor told her to.","She wanted to earn more money.","The friends she made on the net encouraged her.","Her computer broke down."],"explanation":"原文 ''so inspired by the people she met online that she decided to start an IT club''(中段)。"},{"q":"How did the club change the man''s life?","answer":"D","options":["It taught him to play games.","It gave him free software.","It sold him a new computer.","It helped him find work online and get a good job."],"explanation":"原文 ''learnt to look for work online and found a good job''(后段)。"}]'::jsonb, '[{"word":"surf","cn":"浏览"},{"word":"inspire","cn":"激励"},{"word":"benefit","cn":"益处"},{"word":"stuck","cn":"困住"}]'::jsonb, 2, 'required2', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Staying Safe Online', 'Many people enjoy being online, but few stop to think about how to stay safe there. Here are a few simple guidelines worth keeping in mind. First, follow the golden rule of the Internet: if you read or see something that makes you feel uncomfortable, leave the site at once and do not click on anything. Second, protect your privacy. Never give out your home address or phone number, because someone might use the information to steal your identity. Identity theft has become a common and serious problem. Third, be polite to others. Being online is no excuse for being rude, and a rude person can easily become a target for a troll or a cyberbully. A troll posts comments only to stir up trouble, often using several false names, while a cyberbully writes mean things aimed at particular people. The good news is that the more polite you are, the less likely you are to be attacked. A little care can keep your time online both safe and happy.', '说明·上网安全建议', 170, '[{"q":"What does the writer suggest doing if a website makes you uncomfortable?","answer":"A","options":["Leave the site immediately and click nothing.","Post an angry comment.","Share it with your friends.","Stay and read it carefully."],"explanation":"原文 ''leave the site at once and do not click on anything'' 的转述。"},{"q":"Why should you keep your address and phone number private?","answer":"B","options":["So your friends cannot find you.","Because someone might use them to steal your identity.","Because the website charges money for them.","So you can shop more quickly."],"explanation":"原文 ''might use the information to steal your identity''(中段)。"},{"q":"According to the text, how can being polite help you online?","answer":"C","options":["It makes your computer faster.","It gives you more followers.","It makes you less likely to be attacked.","It saves you money."],"explanation":"末段 ''the more polite you are, the less likely you are to be attacked'' 的转述。"}]'::jsonb, '[{"word":"privacy","cn":"隐私"},{"word":"identity","cn":"身份"},{"word":"troll","cn":"喷子"},{"word":"cyberbully","cn":"网霸"}]'::jsonb, 2, 'required2', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Shopping on the Net', 'Online shopping has become part of everyday life for many families. Instead of going out to stores week after week, more and more people now order everything from clothes to food on the net and have it delivered to their homes. There are clear reasons why it is so popular. It is convenient, because you can shop at any hour without leaving the house. It often saves money, too, since many sites offer a discount that you would not find in a normal shop. Yet careful shoppers know that it pays to be wise. Before you buy, use a website that you are familiar with, and read what other buyers say about the goods. Be sure to protect your account by choosing a strong password and never sharing it. If a deal looks far too good to be true, it probably is. Used with a little common sense, online shopping can save both your time and your money.', '说明·网购的方便与小心', 158, '[{"q":"What do many people do instead of going to stores each week?","answer":"D","options":["Stop buying anything new.","Travel to other towns to shop.","Borrow things from neighbours.","Order goods online and have them delivered home."],"explanation":"原文 ''order everything… on the net and have it delivered to their homes'' 的转述。"},{"q":"Why does online shopping often save money?","answer":"A","options":["Because lower prices are often found on the web.","Because the goods are always free.","Because no one ever buys much.","Because it takes a long time."],"explanation":"原文 ''many sites offer a discount that you would not find in a normal shop''(中段)。"},{"q":"What advice does the writer give about your account?","answer":"B","options":["Share it with close friends.","Keep it safe with a strong password and tell no one.","Change it every single day.","Use the same password everywhere."],"explanation":"原文 ''protect your account by choosing a strong password and never sharing it''(后段)。"}]'::jsonb, '[{"word":"discount","cn":"折扣"},{"word":"account","cn":"账户"},{"word":"familiar","cn":"熟悉的"},{"word":"convenient","cn":"方便的"}]'::jsonb, 2, 'required2', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Finding What You Need', 'Long ago, when people wanted to learn about something, they had to spend hours looking through heavy books in a library. Today, a search engine can do much of that work in seconds. A search engine is simply a tool that helps you find what you are looking for on the net. You type in a few words, press a button, and a list of pages appears at once. This has made study far easier, but it has also brought a new problem. Not everything you read online is true, and false information can spread very quickly. So it is wise to learn how to search well. Try to use clear and exact words, and look at more than one site before you believe an answer. It also helps to check who the author is and whether the page gives the sources of its facts. With a little care, a search engine becomes a powerful friend that opens the door to almost endless knowledge.', '说明·搜索引擎与信息检索', 164, '[{"q":"What did people have to do before search engines existed?","answer":"C","options":["Ask robots for answers.","Write their own books first.","Spend hours looking through books in a library.","Wait for the news on TV."],"explanation":"原文 ''spend hours looking through heavy books in a library'' 的转述。"},{"q":"What new problem has the search engine brought?","answer":"D","options":["Books have all disappeared.","People read far too slowly now.","Libraries have become free.","Untrue facts can travel across the net fast."],"explanation":"原文 ''false information can spread very quickly''(中段)。"},{"q":"What does the writer advise readers to do before believing an answer?","answer":"A","options":["Compare several pages and find out who wrote them.","Trust the very first page they see.","Stop using the Internet.","Only read printed books."],"explanation":"原文 ''look at more than one site… check who the author is''(后段)的转述。"}]'::jsonb, '[{"word":"engine","cn":"引擎"},{"word":"false","cn":"假的"},{"word":"author","cn":"作者"},{"word":"press","cn":"按"}]'::jsonb, 2, 'required2', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Small Town Goes Online', 'The Internet has brought great changes to Wuzhen, a small waterside town in Zhejiang. For the past few years, this ancient town has hosted the World Internet Conference, and life there has never been more convenient. Residents can now go online as easily as people in large modern cities, and they can stream films and music at high speeds. The Internet has even changed the way people get around. For short trips, both residents and visitors can use a public bike system; the bikes are rented through online apps, with no need for paperwork or cash. Even the parking system at the conference centre has been made fully Internet-based. The story of Wuzhen shows that no town is too small to join the world of the Internet. If a quiet old town beside the water can take this step, then towns everywhere should be able to do the same, so that everyone can share in what the Internet has to offer.', '说明·乌镇与世界互联网大会', 161, '[{"q":"What has Wuzhen hosted for the past few years?","answer":"B","options":["A national bike race.","The World Internet Conference.","A music festival.","A book fair."],"explanation":"原文 ''has hosted the World Internet Conference'' 的转述。"},{"q":"How can people rent the public bikes in Wuzhen?","answer":"C","options":["By paying with cash at a desk.","By signing a long form.","By using apps on the net, needing no forms or money.","Only the residents may use them."],"explanation":"原文 ''rented through online apps, with no need for paperwork or cash''(中段)。"},{"q":"What main point does the story of Wuzhen make?","answer":"D","options":["Old towns should not change at all.","Only big cities can use the Internet.","Bikes are better than the Internet.","Even the smallest places can become part of the online world."],"explanation":"末段 ''no town is too small to join the world of the Internet'' 的转述。"}]'::jsonb, '[{"word":"resident","cn":"居民"},{"word":"stream","cn":"流播"},{"word":"conference","cn":"会议"},{"word":"province","cn":"省"}]'::jsonb, 2, 'required2', 'U3');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U3', 'A Blog about Online Safety', 'Today I want to (1)____ about a question I am often asked: how do you stay safe online? I am not an expert, but years online have taught me a few useful (2)____. The first rule is simple. If something makes you feel uncomfortable, (3)____ the site at once and don''t click on anything. Second, protect your (4)____. Never give out your home address or phone number, because a stranger might use it to steal your (5)____. Third, always be (6)____ to others. Being rude online can turn you into a (7)____ for a troll, who posts comments only to make (8)____. A troll often uses several (9)____ names so that nobody knows who he really is. Remember these tips, and you can (10)____ the Internet far more safely.', 129, 2, '[{"q":"1","answer":"A","options":["blog","sleep","drive","cook"],"explanation":"blog about 写博客谈论。"},{"q":"2","answer":"B","options":["prices","tips","rivers","songs"],"explanation":"useful tips 有用的建议。"},{"q":"3","answer":"C","options":["build","paint","leave","open"],"explanation":"leave the site 离开网站。"},{"q":"4","answer":"D","options":["weather","garden","weight","privacy"],"explanation":"protect your privacy 保护隐私。"},{"q":"5","answer":"A","options":["identity","dinner","garden","holiday"],"explanation":"steal your identity 盗用身份。"},{"q":"6","answer":"B","options":["angry","polite","tired","hungry"],"explanation":"be polite 有礼貌。"},{"q":"7","answer":"C","options":["garden","ticket","target","letter"],"explanation":"a target for a troll 攻击目标。"},{"q":"8","answer":"D","options":["money","noise","music","trouble"],"explanation":"make trouble 惹是生非。"},{"q":"9","answer":"A","options":["false","kind","happy","warm"],"explanation":"false names 假名。"},{"q":"10","answer":"B","options":["sell","surf","build","cook"],"explanation":"surf the Internet 上网浏览。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U3', 'Grandpa Learns to Use the Net', 'Last year my grandpa, who is over seventy, finally decided to (1)____ how to use the Internet. At first he found it very (2)____, and he often got stuck. "Why do I need this?" he would ask. But my sister and I were (3)____ and showed him a little every day. Slowly, things began to change. He learned to (4)____ on a link, to send an email, and even to (5)____ photos of his garden to his old friends. One day he (6)____ a video chat app and saw the face of his brother, who lives far away in another (7)____. His eyes filled with tears of joy. Now Grandpa says the Internet has removed the (8)____ between him and the people he loves. He even keeps (9)____ of the news every morning. Helping him has taught me that no one is too old to enjoy the (10)____ of new technology.', 151, 2, '[{"q":"1","answer":"C","options":["throw","sell","learn","cook"],"explanation":"learn how to 学会如何。"},{"q":"2","answer":"D","options":["tasty","warm","loud","tough"],"explanation":"very tough 很难。"},{"q":"3","answer":"A","options":["patient","lazy","angry","absent"],"explanation":"be patient 有耐心。"},{"q":"4","answer":"B","options":["sleep","click","cook","drive"],"explanation":"click on a link 点击链接。"},{"q":"5","answer":"C","options":["eat","burn","send","drop"],"explanation":"send photos 发送照片。"},{"q":"6","answer":"D","options":["ate","sold","lost","opened"],"explanation":"opened a video chat app 打开应用。"},{"q":"7","answer":"A","options":["province","garden","kitchen","market"],"explanation":"another province 另一个省。"},{"q":"8","answer":"B","options":["price","distance","noise","weather"],"explanation":"removed the distance 消除距离。"},{"q":"9","answer":"C","options":["rain","noise","track","sport"],"explanation":"keep track of 了解……的动态。"},{"q":"10","answer":"D","options":["price","noises","seasons","benefits"],"explanation":"the benefits of 好处。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U3', 'Choosing the Right App', 'Xiao Bo and Laura were (1)____ about which apps to put on their phones. Xiao Bo said he was looking for an app to help him get in (2)____, because he wanted to exercise more. Laura, however, wanted one that would help her (3)____ money while shopping. "My guess is that this one would be (4)____ for you," Xiao Bo said, showing her an app that finds the best (5)____ in online shops. "And I think this fitness app could help me (6)____ more steps every day." Before they (7)____ anything, they read what other users had written. Some reviews were good, but a few warned that one app would quickly use up the phone''s (8)____. In the end, each of them chose an app they could (9)____, and both were happy with their choice. A good app, they agreed, should be both useful and easy to (10)____.', 148, 2, '[{"q":"1","answer":"A","options":["talking","sleeping","running","cooking"],"explanation":"talking about 谈论。"},{"q":"2","answer":"B","options":["price","shape","rain","noise"],"explanation":"get in shape 健身;身材好。"},{"q":"3","answer":"C","options":["lose","burn","save","throw"],"explanation":"save money 省钱。"},{"q":"4","answer":"D","options":["angry","asleep","absent","useful"],"explanation":"be useful 有用。"},{"q":"5","answer":"A","options":["discounts","rivers","songs","clouds"],"explanation":"the best discounts 折扣。"},{"q":"6","answer":"B","options":["eat","take","drop","burn"],"explanation":"take more steps 走更多步。"},{"q":"7","answer":"C","options":["ate","sang","downloaded","slept"],"explanation":"downloaded anything 下载。"},{"q":"8","answer":"D","options":["garden","weather","season","battery"],"explanation":"the phone''s battery 手机电池。"},{"q":"9","answer":"A","options":["trust","throw","burn","sell"],"explanation":"an app they could trust 信任。"},{"q":"10","answer":"B","options":["lose","use","drop","burn"],"explanation":"easy to use 易用。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U3', 'Trouble in the Chat Room', 'Last year our online chat room had a serious (1)____. Mean comments were being posted by someone we did not (2)____, and several members began to feel (3)____. One girl was so unhappy that she almost wanted to (4)____ the group. We knew we had to do something. First, we agreed to stay (5)____ and never answer the rude messages, because that is exactly what a (6)____ wants. Next, we reported the user to the people who (7)____ the website. They soon found out that the same person was using two (8)____ names. After his account was closed, the mean comments finally (9)____. The room became a friendly place again. The whole experience taught us an important (10)____: a calm and polite group is much harder to attack.', 128, 2, '[{"q":"1","answer":"C","options":["holiday","garden","problem","song"],"explanation":"a serious problem 严重问题。"},{"q":"2","answer":"D","options":["cook","burn","sell","know"],"explanation":"did not know 不认识。"},{"q":"3","answer":"A","options":["upset","happy","warm","rich"],"explanation":"feel upset 难过。"},{"q":"4","answer":"B","options":["build","leave","paint","cook"],"explanation":"leave the group 离开群组。"},{"q":"5","answer":"C","options":["angry","absent","calm","loud"],"explanation":"stay calm 保持冷静。"},{"q":"6","answer":"D","options":["teacher","doctor","farmer","troll"],"explanation":"what a troll wants 喷子想要的。"},{"q":"7","answer":"A","options":["ran","ate","burned","lost"],"explanation":"the people who ran the website 管理网站。"},{"q":"8","answer":"B","options":["warm","false","kind","happy"],"explanation":"two false names 两个假名。"},{"q":"9","answer":"C","options":["grew","shone","stopped","rained"],"explanation":"comments stopped 停止。"},{"q":"10","answer":"D","options":["price","noise","garden","lesson"],"explanation":"an important lesson 教训。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U3', 'Installing New Software', 'Yesterday my phone became very (1)____, and it took ages to open even a simple page. A friend told me that a new piece of (2)____ might solve the problem. So I went to a website I was (3)____ with and started to download it. A box appeared, asking me to (4)____ a strong password for my new account. After I typed it in, I had to (5)____ a button to start the download. While I waited, I went to make a cup of tea. When I came back, the software had been (6)____ onto my phone, and a message said it was (7)____. I opened it at once. To my surprise, my phone now ran much (8)____ than before, and the (9)____ even lasted longer. It just shows that, used wisely, the right software can give an old phone a whole new (10)____.', 144, 2, '[{"q":"1","answer":"A","options":["slow","warm","tasty","loud"],"explanation":"very slow 很慢。"},{"q":"2","answer":"B","options":["weather","software","garden","season"],"explanation":"a piece of software 一款软件。"},{"q":"3","answer":"C","options":["angry","absent","familiar","asleep"],"explanation":"familiar with 熟悉的。"},{"q":"4","answer":"D","options":["eat","burn","throw","choose"],"explanation":"choose a password 设置密码。"},{"q":"5","answer":"A","options":["press","eat","burn","sing"],"explanation":"press a button 按按钮。"},{"q":"6","answer":"B","options":["eaten","downloaded","burned","sold"],"explanation":"had been downloaded 被下载(现在完成被动)。"},{"q":"7","answer":"C","options":["asleep","absent","ready","angry"],"explanation":"it was ready 准备好了。"},{"q":"8","answer":"D","options":["slower","worse","smaller","faster"],"explanation":"much faster 快得多。"},{"q":"9","answer":"A","options":["battery","weather","garden","season"],"explanation":"the battery lasted longer 电池更耐用。"},{"q":"10","answer":"B","options":["price","life","noise","garden"],"explanation":"a whole new life 新生命。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U3', 'My Social Media Habits', 'Like many students, I used to spend hours on (1)____ media every day. I would check my phone the moment I woke up, and I kept (2)____ of every new message and photo my friends posted. It felt good at first, but soon I noticed some (3)____ effects. I was sleeping less, and I felt (4)____ whenever I saw others having more fun than me. My marks at school began to (5)____, too. So I decided to make a change. Now I turn (6)____ all the apps an hour before bed, and I only check them at certain (7)____ during the day. I also try to share things that make people (8)____ rather than sad. These small steps have already made a big (9)____. I feel calmer, I sleep better, and I have more time for the things that really (10)____ to me.', 143, 2, '[{"q":"1","answer":"C","options":["angry","absent","social","loud"],"explanation":"social media 社交媒体。"},{"q":"2","answer":"D","options":["rain","noise","sport","track"],"explanation":"keep track of 关注……动态。"},{"q":"3","answer":"A","options":["bad","tasty","warm","kind"],"explanation":"bad effects 不良影响。"},{"q":"4","answer":"B","options":["happy","upset","warm","rich"],"explanation":"feel upset 难过。"},{"q":"5","answer":"C","options":["grow","shine","fall","rain"],"explanation":"marks fall 成绩下降。"},{"q":"6","answer":"D","options":["into","over","along","off"],"explanation":"turn off the apps 关掉应用。"},{"q":"7","answer":"A","options":["times","gardens","rivers","songs"],"explanation":"at certain times 在特定时间。"},{"q":"8","answer":"B","options":["sad","smile","angry","tired"],"explanation":"make people smile 让人微笑。"},{"q":"9","answer":"C","options":["noise","garden","difference","price"],"explanation":"made a big difference 带来很大不同。"},{"q":"10","answer":"D","options":["lose","burn","drop","matter"],"explanation":"things that matter 重要的事。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·对话 Online Habits Survey', '必修二 U3 · dialogue', 3, 'Sam: Hi Anna, I''m doing a survey on online habits. How much time do you spend online every day?
