INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write a Blog about Online Safety(写一篇关于上网安全的博客)', 'Stay Safe Online', '假设你叫李华,你常逛一个中国学生交流上网经验的论坛。请用英语写一篇约100词的博客,谈谈如何安全上网,内容包括:① 简单说明为什么上网安全很重要;② 给出两三条具体的安全上网建议(如保护隐私、用强密码、对人有礼貌);③ 邀请读者在下方留言分享自己的经验。注意:每句围绕中心、代词指代清楚、可适当使用现在完成时的被动语态。', 'Suppose you are Li Hua. You often visit a forum where Chinese students share their experiences online. Write a blog post (about 100 words) about how to stay safe online, including: 1) a short note on why online safety matters; 2) two or three clear tips for staying safe (e.g. protect your privacy, use strong passwords, be polite); 3) an invitation for readers to leave their own experiences in the comments below.', '["说明上网安全的重要性(why it matters)","给出2-3条具体建议(Protect your privacy. / Use a strong password. / Be polite.)","解释关键词或举例(Identity theft is …)","邀请读者留言(Post your comments below!)"]'::jsonb, 70, 100, 'Hi everyone! Today I''d like to blog about a question I am often asked: how do you stay safe online? It matters because much harm has been done to people who share too much. First, protect your privacy. Never give out your home address or phone number, because someone might use the information to steal your identity. Identity theft is a common and serious problem. Second, use a strong password for every account, and never share it. Third, be polite, so you don''t become a target for a troll or cyberbully. The more careful you are, the safer you will be. Have you had any bad experiences online? Post your comments below!', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Today I''d like to blog about how to stay safe online.","Never give out your home address, because someone might use it to steal your identity.","Use a strong password for every account, and never share it.","The more careful you are, the safer you will be."]'::jsonb, '[{"wrong":"Much harm has did to people.","correct":"Much harm has been done to people.","note":"现在完成时被动:has/have been + 过去分词。"},{"wrong":"Protect your privacy is important.","correct":"Protecting your privacy is important.","note":"动词作主语用动名词 -ing 形式。"},{"wrong":"Someone might steal your identity by the information.","correct":"Someone might use the information to steal your identity.","note":"''用某物做某事''用 use sth to do,不用 by。"}]'::jsonb, '【上网安全博客结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required2', 'U3', '{"title":"现在完成时的被动语态·has/have been + 过去分词 速查","intro":"当主语是动作的承受者、且动作''到现在已完成或有当前影响''时,用现在完成时的被动:has/have been + 过去分词。口诀:has/have + been + done。","table":{"headers":["句型","结构 / 例句"],"rows":[["肯定句","主语 + has/have been + 过去分词:The software has been downloaded."],["否定句","主语 + hasn''t/haven''t been + 过去分词:The file hasn''t been copied yet."],["一般疑问","Has/Have + 主语 + been + 过去分词?:Has the password been confirmed?"],["带 by 短语","主语 + has/have been + done + by + 执行者:Jan''s life has been improved by the Internet."]]},"specialRules":[{"rule":"单数主语(及不可数名词)用 has been done,复数及 I/you/we/they 用 have been done","mark":"The PC has been built. / Many people have been helped."},{"rule":"主动变被动:主动宾语→被动主语,动词改 has/have been + 过去分词,执行者用 by 引出","mark":"They''ve built a new PC. → A new PC has been built (by them)."},{"rule":"时间副词 already/just 放 been 前,yet 放句末(多用于否定/疑问)","mark":"has already been done / hasn''t been done yet"},{"rule":"疑问句把 has/have 提到主语前,过去分词不变","mark":"Has anyone made a comment? → Has a comment been made?"}],"why":["被动语态把''谁承受动作''放在主语位置;再叠加现在完成时的''have/has + 过去分词'',就得到 has/have been + 过去分词——既表被动,又表''到现在已完成''。"],"gaokaoPoints":["语法填空/改错高频:看主语是不是动作承受者,是→用被动;再判断''已完成''语境(already/yet/just/since/recently)→现在完成时被动。","主谓一致:被动主语决定 has 还是 have,与执行者(by 后)无关。"],"examVsReal":[{"exam":"The software has been downloaded.（考试/书面规范）","real":"The software''s downloaded. / It''s all set up.","note":"口语常缩写 has→''s,或用 be done/be all set 等更简洁的说法"},{"exam":"Has the password been confirmed?（考试)","real":"Did you confirm the password? / Is the password set?","note":"日常口语里常用主动一般过去时或 be done 提问,语义相近"}]}'::jsonb);
